from pathlib import Path

APP=Path('src/AppFinal.tsx')
API=Path('src/index-final.ts')
s=APP.read_text()
b=API.read_text()

def once(text, old, new, label):
    if old not in text:
        if new in text: return text
        raise SystemExit(f'anchor not found: {label}')
    return text.replace(old,new,1)

def block(text,start,end,new,label):
    a=text.find(start)
    z=text.find(end,a)
    if a<0 or z<0: raise SystemExit(f'block not found: {label}')
    return text[:a]+new+text[z:]

# Icons / types / helpers
