admin_order=r'''function AdminInstitutionOrderEntry({boot,user}:{boot:Bootstrap;user:User}){if(!isAdmin(user)||!permitted(boot,'ORDERS_CREATE'))return <Empty text="Bu bölüm yalnız yetkili yönetici kullanıcılarına açıktır."/>;const[inst,setInst]=useState(boot.institutions[0]?.id||''),[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||''),[grade,setGrade]=useState(''),[publisher,setPublisher]=useState(''),[month,setMonth]=useState(''),[q,setQ]=useState(''),[selected,setSelected]=useState<Set<string>>(new Set()),[qty,setQty]=useState<Record<string,string>>({}),[msg,setMsg]=useState('');const exams=useAsync(()=>api(`/api/exams?season_id=${season}&active=1${grade?`&grade_level_id=${grade}`:''}${publisher?`&publisher_id=${publisher}`:''}${month?`&month=${month}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`),[season,grade,publisher,month,q]);const items=(exams.data as any)?.items||[];const toggle=(id:string)=>setSelected(v=>{const n=new Set(v);n.has(id)?n.delete(id):n.add(id);return n});const saveOne=async(x:any)=>{const n=Number(qty[x.id]||0);if(n<=0)return alert('Adet girin.');await api('/api/orders',{method:'POST',body:JSON.stringify({institution_id:inst,exam_id:x.id,quantity:n})});setMsg(`${x.name}: ${n} adet sipariş kaydedildi.`);setQty({...qty,[x.id]:''});setSelected(v=>{const n=new Set(v);n.delete(x.id);return n})};const saveBulk=async()=>{const rows=[...selected].map(id=>({exam_id:id,quantity:Number(qty[id]||0)}));if(!inst||!rows.length)return;const invalid=rows.find(x=>x.quantity<=0);if(invalid)return alert('Seçili her deneme için adet girin.');const d=await api('/api/orders/bulk',{method:'POST',body:JSON.stringify({institution_id:inst,items:rows})});setMsg(`${d.created||0} sipariş oluşturuldu${d.errors?.length?`, ${d.errors.length} kayıt atlandı`:''}.`);setSelected(new Set());setQty({})};return <><div className="admin-order-hero"><div><span className="pill gold"><ShoppingCart size={14}/> Yönetici Sipariş Girişi</span><h2>Kuruma Sipariş Gir</h2><p>Kurum seçin; sipariş geldikçe tek tek veya birden fazla denemeyi toplu kaydedin.</p></div><div className="admin-order-inst"><label>Kurum</label><select value={inst} onChange={e=>setInst(e.target.value)}>{boot.institutions.filter(i=>i.is_active!==0).map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></div></div><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><select value={publisher} onChange={e=>setPublisher(e.target.value)}><option value="">Tüm yayınevleri</option>{boot.publishers.map(p=><option key={p.id} value={p.id}>{p.short_name||p.name}</option>)}</select><select value={month} onChange={e=>setMonth(e.target.value)}><option value="">Tüm aylar</option>{MONTHS.map(m=><option value={m.v} key={m.v}>{m.n}</option>)}</select><SearchBox value={q} set={setQ}/><div className="spacer"/><button className="btn primary" disabled={!selected.size} onClick={saveBulk}>{selected.size} Seçileni Toplu Kaydet</button></Toolbar>{msg&&<div className="success-box"><CheckCircle2 size={18}/>{msg}</div>}<DataTable cols={['Seç','Sınıf','Yayınevi','Deneme','Son Sipariş','Uygulama','Adet','']} rows={items.map((x:any)=>[<input key="c" type="checkbox" checked={selected.has(x.id)} onChange={()=>toggle(x.id)}/>,x.grade_name,x.publisher_short||x.publisher_name,x.name,fmtDate(x.last_order_date),`${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`,<input key="q" className="qty-inline" type="number" min="1" value={qty[x.id]||''} onChange={e=>setQty({...qty,[x.id]:e.target.value})}/>,<button key="b" className="btn tiny" onClick={()=>saveOne(x)}>Sipariş Gir</button>])}/></>}

'''
