# Orders respect current user's granular permissions.
old="function Orders({boot,user}:{boot:Bootstrap;user:User}){const q=useAsync(()=>api('/api/orders'),[]),[edit,setEdit]=useState<any|null>(null),[modal,setModal]=useState(false);const items=(q.data as any)?.items||[];const patch=async(x:any,b:any)=>{await api(`/api/orders/${x.id}`,{method:'PATCH',body:JSON.stringify(b)});q.reload()};const remove=async(x:any)=>{if(!confirm('Sipariş silinsin veya operasyon başladıysa iptal edilsin mi?'))return;await api(`/api/orders/${x.id}`,{method:'DELETE'});q.reload()};return <><Toolbar><div className=\"spacer\"/><button className=\"btn primary\" onClick={()=>setModal(true)}><Plus size={16}/> Sipariş Gir</button></Toolbar>"
new="function Orders({boot,user}:{boot:Bootstrap;user:User}){const q=useAsync(()=>api('/api/orders'),[]),[edit,setEdit]=useState<any|null>(null),[modal,setModal]=useState(false);const items=(q.data as any)?.items||[],canCreate=permitted(boot,'ORDERS_CREATE'),canEdit=permitted(boot,'ORDERS_EDIT'),canDelete=permitted(boot,'ORDERS_DELETE');const patch=async(x:any,b:any)=>{await api(`/api/orders/${x.id}`,{method:'PATCH',body:JSON.stringify(b)});q.reload()};const remove=async(x:any)=>{if(!confirm('Bu sipariş silinsin mi? İşlem geçmişi denetim kaydında korunacaktır.'))return;await api(`/api/orders/${x.id}`,{method:'DELETE'});q.reload()};return <><Toolbar><div className=\"spacer\"/>{canCreate&&<button className=\"btn primary\" onClick={()=>setModal(true)}><Plus size={16}/> Sipariş Gir</button>}</Toolbar>"
s=once(s,old,new,'orders permissions start')
s=s.replace('<Actions key="a"><button onClick={()=>setEdit(x)}><Pencil size={15}/></button><button className="danger" onClick={()=>remove(x)}><Trash2 size={15}/></button></Actions>','<Actions key="a">{canEdit&&<button onClick={()=>setEdit(x)} title="Düzenle"><Pencil size={15}/></button>}{canDelete&&<button className="danger" onClick={()=>remove(x)} title="Sil"><Trash2 size={15}/></button>}</Actions>',1)

# Publisher cards become drill-down catalog browser.
new_publisher=r'''function PublisherList({boot,user,refreshBoot}:{boot:Bootstrap;user:User;refreshBoot:()=>Promise<void>}){const q=useAsync(()=>api('/api/publishers'),[]),[edit,setEdit]=useState<any|null>(null),[selected,setSelected]=useState<any|null>(null);const items=(q.data as any)?.items||boot.publishers;const remove=async(x:any)=>{if(!confirm(`${x.name} silinsin/pasife alınsın mı?`))return;await api(`/api/publishers/${x.id}`,{method:'DELETE'});q.reload();refreshBoot()};const toggle=async(x:any)=>{await api(`/api/publishers/${x.id}`,{method:'PATCH',body:JSON.stringify({is_active:!x.is_active})});q.reload();refreshBoot()};return <><div className="card-grid">{items.map((x:any)=><div className={`publisher-card clickable ${!x.is_active?'inactive':''}`} key={x.id} onClick={()=>setSelected(x)}><div className="publisher-mark">{x.logo_url?<img src={x.logo_url}/>:x.short_name?.slice(0,3).toUpperCase()}</div><div className="publisher-content"><h3>{x.name}</h3><p>{x.sales_representative||x.contact_person||'Yetkili tanımlanmadı'}</p><small>{x.phone||'—'} · Denemeleri görmek için tıklayın</small></div>{isAdmin(user)&&<Actions><button onClick={e=>{e.stopPropagation();setEdit(x)}}><Pencil size={15}/></button><button onClick={e=>{e.stopPropagation();toggle(x)}}>{x.is_active?<ToggleRight size={17}/>:<ToggleLeft size={17}/>}</button><button className="danger" onClick={e=>{e.stopPropagation();remove(x)}}><Trash2 size={15}/></button></Actions>}</div>)}</div>{isAdmin(user)&&<button className="fab" onClick={()=>setEdit({})}><Plus/></button>}{selected&&<PublisherExamBrowser boot={boot} publisher={selected} close={()=>setSelected(null)}/>} {edit&&<PublisherModal item={edit.id?edit:null} close={()=>setEdit(null)} saved={async()=>{setEdit(null);await refreshBoot();q.reload()}}/>}</>}
function PublisherExamBrowser({boot,publisher,close}:{boot:Bootstrap;publisher:any;close:()=>void}){const[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||''),[grade,setGrade]=useState(''),[active,setActive]=useState('1'),[month,setMonth]=useState(''),[q,setQ]=useState('');const list=useAsync(()=>api(`/api/exams?publisher_id=${publisher.id}&season_id=${season}${grade?`&grade_level_id=${grade}`:''}${active?`&active=${active}`:''}${month?`&month=${month}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`),[publisher.id,season,grade,active,month,q]);const items=(list.data as any)?.items||[];return <Modal title={`${publisher.name} · Deneme Kataloğu`} close={close}><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><select value={active} onChange={e=>setActive(e.target.value)}><option value="1">Aktif</option><option value="0">Pasif</option><option value="">Tümü</option></select><select value={month} onChange={e=>setMonth(e.target.value)}><option value="">Tüm aylar</option>{MONTHS.map(m=><option key={m.v} value={m.v}>{m.n}</option>)}</select><SearchBox value={q} set={setQ}/></Toolbar>{list.loading?<Loading/>:<DataTable cols={['Tarih','Sınıf','Tür','Zorluk','Deneme','Kod','Son Sipariş','Uygulama']} rows={items.map((x:any)=>[fmtDate(x.application_start_date),x.grade_name,x.exam_type||'DENEME',x.difficulty_level||'—',x.name,x.code,fmtDate(x.last_order_date),`${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`])}/>} {!items.length&&!list.loading&&<Empty text="Bu filtrelerde tanımlı deneme yok."/>}</Modal>}
'''
