b=b.replace(insert_point,extra_api+insert_point,1)

# reminder generator before export
export_anchor='export default app;'
reminder=r'''async function generateExamReminders(env:Env){await ensure(env.DB);const exams=await env.DB.prepare(`SELECT e.id,e.name,e.last_order_date,g.name grade_name,p.name publisher_name FROM exams e JOIN grade_levels g ON g.id=e.grade_level_id JOIN publishers p ON p.id=e.publisher_id WHERE e.is_active=1 AND e.deleted_at IS NULL AND e.last_order_date BETWEEN date('now') AND date('now','+7 day') ORDER BY e.last_order_date`).all<any>();let created=0,phoneSent=0;for(const ex of exams.results||[]){const days=Math.round((new Date(`${ex.last_order_date}T12:00:00Z`).getTime()-new Date(`${today()}T12:00:00Z`).getTime())/86400000);if(![0,1,3,7].includes(days))continue;const kind=days===0?'SON_GUN':`SON_SIPARIS_${days}G`,title=days===0?'Bugün son sipariş günü':`Son siparişe ${days} gün kaldı`,message=`${ex.publisher_name} · ${ex.grade_name} · ${ex.name} — son sipariş ${ex.last_order_date}`;const recipients=await env.DB.prepare(`SELECT DISTINCT u.id,u.phone,u.notification_enabled FROM users u WHERE u.status='ACTIVE' AND u.deleted_at IS NULL AND (u.role='SUPER_ADMIN' OR (u.role='ADMIN') OR (u.role='PERSONEL' AND EXISTS(SELECT 1 FROM institution_exam_plans ip JOIN institutions i ON i.id=ip.institution_id WHERE ip.exam_id=? AND i.staff_id=u.id)))`).bind(ex.id).all<any>();for(const user of recipients.results||[]){const rid=uid('rem');try{const ins=await env.DB.prepare(`INSERT OR IGNORE INTO reminder_delivery_log(id,user_id,exam_id,reminder_type,reminder_date,channel,status,created_at) VALUES(?,?,?,?,?,'IN_APP','CREATED',?)`).bind(rid,user.id,ex.id,kind,today(),now()).run();if(Number((ins.meta as any)?.changes||0)>0){await env.DB.prepare(`INSERT INTO notifications(id,user_id,type,title,message,related_id,is_read,created_at) VALUES(?,?,?,?,?,?,0,?)`).bind(uid('notice'),user.id,'EXAM_DEADLINE',title,message,ex.id,now()).run();created++}}catch{}if(user.notification_enabled&&user.phone&&env.PHONE_NOTIFICATION_WEBHOOK_URL){const logId=uid('rem');try{const check=await env.DB.prepare(`SELECT id FROM reminder_delivery_log WHERE user_id=? AND exam_id=? AND reminder_type=? AND reminder_date=? AND channel='PHONE'`).bind(user.id,ex.id,kind,today()).first();if(!check){const res=await fetch(env.PHONE_NOTIFICATION_WEBHOOK_URL,{method:'POST',headers:{'Content-Type':'application/json',...(env.PHONE_NOTIFICATION_WEBHOOK_TOKEN?{'Authorization':`Bearer ${env.PHONE_NOTIFICATION_WEBHOOK_TOKEN}`}:{})},body:JSON.stringify({phone:user.phone,title,message,type:kind,exam_id:ex.id})});await env.DB.prepare(`INSERT INTO reminder_delivery_log(id,user_id,exam_id,reminder_type,reminder_date,channel,status,provider_response,created_at) VALUES(?,?,?,?,?,'PHONE',?,?,?)`).bind(logId,user.id,ex.id,kind,today(),res.ok?'SENT':'FAILED',String(res.status),now()).run();if(res.ok)phoneSent++}}catch(e:any){await env.DB.prepare(`INSERT OR IGNORE INTO reminder_delivery_log(id,user_id,exam_id,reminder_type,reminder_date,channel,status,provider_response,created_at) VALUES(?,?,?,?,?,'PHONE','FAILED',?,?)`).bind(logId,user.id,ex.id,kind,today(),String(e?.message||e),now()).run()}}}}return{created,phone_sent:phoneSent,provider_configured:!!env.PHONE_NOTIFICATION_WEBHOOK_URL}}

export default {fetch:app.fetch,scheduled:async(_controller:any,env:Env,ctx:any)=>{ctx.waitUntil(generateExamReminders(env))}};
'''
b=once(b,export_anchor,reminder,'scheduled reminders')

